import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load ceramic grain texture
  const textureMap = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');

  // Badge plane geometry (capsule proportions: 0.8w × 0.3h)
  const geometry = new THREE.PlaneGeometry(0.8, 0.3);

  // Main material: paper color base with ceramic texture
  const material = new MeshBasicNodeMaterial({
    map: textureMap,
    color: 0xe8ecf2,
    side: THREE.DoubleSide,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene transform from config
  const scenePos = config.scenePosition || { x: 1.25, y: 0.7, z: 0 };
  const sceneRot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const sceneScale = config.sceneScale || { x: 1, y: 1, z: 1 };

  mesh.position.set(scenePos.x, scenePos.y, scenePos.z);
  mesh.rotation.set(sceneRot.x, sceneRot.y, sceneRot.z);
  mesh.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  group.add(mesh);

  // Accent edge (signal red emissive glow, visible on focus)
  const edgeGeometry = new THREE.PlaneGeometry(0.85, 0.35);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 0.5,
    side: THREE.DoubleSide,
    transparent: true,
  });

  const edgeMesh = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.z = -0.001;
  mesh.add(edgeMesh);
  edgeMesh.visible = false;

  // Animation state
  let hoverTimeline = null;

  // Interaction handlers
  group.userData.handlers = {
    pointerenter() {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(mesh.position, {
        y: scenePos.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    pointerleave() {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(mesh.position, {
        y: scenePos.y,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    click() {
      ctx.onEvent?.('hub-pricing.select');
    },
    focus() {
      edgeMesh.visible = true;
    },
    blur() {
      edgeMesh.visible = false;
    },
  };

  // Resource cleanup
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    geometry.dispose();
    edgeGeometry.dispose();
    material.dispose();
    edgeMaterial.dispose();
    textureMap.dispose();
  };

  return group;
}
